#include <algorithm>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;class DiscountStrategy{public:virtual~DiscountStrategy()=default;virtual double apply(double x)const=0;};class PercentDiscount:public DiscountStrategy{double p;public:explicit PercentDiscount(double x):p(x){}double apply(double x)const override{return x*(1-p);}};class PaymentStrategy{public:virtual~PaymentStrategy()=default;virtual bool process(double)=0;virtual string name()const=0;};class CardPayment:public PaymentStrategy{public:bool process(double a)override{cout<<"Card authorized "<<a<<'\n';return a>0;}string name()const override{return"Card";}};class CashOnDelivery:public PaymentStrategy{public:bool process(double a)override{cout<<"COD "<<a<<'\n';return a>0;}string name()const override{return"COD";}};
class Product{protected:int id;string name,category;double price;int quantity;public:Product(int i,string n,string c,double p,int q):id(i),name(move(n)),category(move(c)),price(p),quantity(q){}virtual~Product()=default;int getId()const{return id;}const string&getName()const{return name;}int stock()const{return quantity;}virtual string detail()const=0;virtual double priceNow()const{return price;}bool take(int q){if(q<=0||q>quantity)return false;quantity-=q;return true;}void addStock(int q){quantity+=q;}void show()const{cout<<id<<" | "<<name<<" | "<<category<<" | "<<priceNow()<<" | stock "<<quantity<<" | "<<detail()<<'\n';}};class Electronics:public Product{string brand;public:Electronics(int i,string n,double p,int q,string b):Product(i,move(n),"Electronics",p,q),brand(move(b)){}string detail()const override{return brand;}};class Clothing:public Product{string size;public:Clothing(int i,string n,double p,int q,string s):Product(i,move(n),"Clothing",p,q),size(move(s)){}string detail()const override{return size;}double priceNow()const override{return price*.95;}};class Grocery:public Product{string expiry;public:Grocery(int i,string n,double p,int q,string e):Product(i,move(n),"Grocery",p,q),expiry(move(e)){}string detail()const override{return expiry;}};
struct CartItem{shared_ptr<Product>p;int q;double subtotal()const{return p->priceNow()*q;}};class Cart{vector<CartItem>items;public:void add(shared_ptr<Product>p,int q){if(!p||q<=0||q>p->stock())throw runtime_error("invalid quantity");items.push_back({p,q});}const auto&all()const{return items;}double subtotal()const{double t=0;for(auto&x:items)t+=x.subtotal();return t;}void clear(){items.clear();}void show()const{for(auto&x:items)cout<<x.p->getName()<<" x"<<x.q<<" = "<<x.subtotal()<<'\n';cout<<"Subtotal "<<subtotal()<<'\n';}};struct Order{int id;double total;string status,payment;};class ShoppingSystem{vector<shared_ptr<Product>>products;vector<Order>orders;Cart cart;int next=1;double discount=.0;shared_ptr<Product>find(int id){for(auto&p:products)if(p->getId()==id)return p;return{};}public:ShoppingSystem(){products.push_back(make_shared<Electronics>(1,"Laptop",35000,8,"Nova"));products.push_back(make_shared<Clothing>(2,"Jacket",1800,15,"L"));products.push_back(make_shared<Grocery>(3,"Coffee",250,30,"2027-06"));}void browse()const{for(auto&p:products)p->show();}void checkout(){if(cart.all().empty())return;double total=PercentDiscount(discount).apply(cart.subtotal());int c;cout<<"Payment 1 Card 2 COD: ";cin>>c;unique_ptr<PaymentStrategy>pay=c==1?unique_ptr<PaymentStrategy>(new CardPayment):unique_ptr<PaymentStrategy>(new CashOnDelivery);if(!pay->process(total))return;for(auto&x:cart.all())if(!x.p->take(x.q))return;orders.push_back({next++,total,"Placed",pay->name()});ofstream("orders.txt",ios::app)<<orders.back().id<<'|'<<total<<'|'<<orders.back().payment<<'\n';cart.clear();}void run(){for(;;){cout<<"\nAdvanced Shopping\n1 Browse 2 Add cart 3 Cart 4 Promo 5 Checkout 6 Orders 7 Inventory 0 Exit\n";int c;if(!(cin>>c)||c==0)break;if(c==1)browse();else if(c==2){int id,q;browse();cin>>id>>q;try{cart.add(find(id),q);}catch(exception&e){cout<<e.what()<<'\n';}}else if(c==3)cart.show();else if(c==4){double p;cin>>p;discount=max(0.0,min(.5,p/100));}else if(c==5)checkout();else if(c==6)for(auto&o:orders)cout<<o.id<<" | "<<o.total<<" | "<<o.status<<" | "<<o.payment<<'\n';else if(c==7){int id,q;cin>>id>>q;if(auto p=find(id))p->addStock(q);}}}};int main(){ShoppingSystem{}.run();}
